Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define LL long long
#define pb push_back
#define mp make_pair
#define pii pair<int,int>
using namespace std;

inline int read_input(){
    int v=0,f=1;
    char c=getchar();
    while (c<'0' || c>'9'){
        if (c=='-') f=-1;
        c=getchar();
    }
    while (c>='0' && c<='9'){
        v=v*10+c-'0';
        c=getchar();
    }
    return v*f;
}

const int Maxn=10;
const LL MOD=1000000007;

LL fast_pow(LL base, LL exp){
    LL res=1;
    while (exp){
        if (exp & 1) res=res*base%MOD;
        base=base*base%MOD;
        exp>>=1;
    }
    return res;
}

LL mod_inv(LL x){
    return fast_pow(x, MOD-2);
}

int p[Maxn][Maxn], n;
int id[64], count_id, Xarr[1048576], Yarr[1048576];

void update_add(int &x, int y){
    x+=y;
    if (x>=MOD) x-=MOD;
}

void update_subtract(int &x, int y){
    x-=y;
    if (x<0) x+=MOD;
}

void fw_transform(int *arr, int mode){
    int N=1048576;
    for (int len=2; len<=N; len<<=1){
        for (int start=0; start<N; start+=len){
            for (int k=start; k<start+(len>>1); ++k){
                if (mode==1) update_add(arr[k], arr[k+(len>>1)]);
                else update_subtract(arr[k], arr[k+(len>>1)]);
            }
        }
    }
}

int main(){
    int n=read_input();
    for (int i=0; i<n; i++){
        for (int j=0; j<n; j++){
            p[i][j]=1LL*read_input()*mod_inv(100)%MOD;
        }
    }
    if (n<6){
        for (int i=n; i<6; i++) p[i][i]=1;
        n=6;
    }
    int A=(1<<6)-1;
    for (int i=0; i<64; i++){
        if (__builtin_popcount(i)==3) id[i]=count_id++;
    }
    for (int mask=0; mask<(1<<18); mask++){
        int msk1=mask&A, msk2=(mask>>6)&A, msk3=(mask>>12)&A;
        int combined_mask=0;
        LL probability=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) probability=probability*p[0][j]%MOD;
            else probability=probability*(MOD+1-p[0][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) probability=probability*p[1][j]%MOD;
            else probability=probability*(MOD+1-p[1][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) probability=probability*p[2][j]%MOD;
            else probability=probability*(MOD+1-p[2][j])%MOD;
        }
        if (probability==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                combined_mask|=1<<id[nmsk];
                            }
                        }
                    }
                }
            }
        }
        update_add(Yarr[combined_mask], int(probability));
    }

    for (int mask=0; mask<(1<<18); mask++){
        int msk1=mask&A, msk2=(mask>>6)&A, msk3=(mask>>12)&A;
        int combined_mask=0;
        LL probability=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) probability=probability*p[3][j]%MOD;
            else probability=probability*(MOD+1-p[3][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) probability=probability*p[4][j]%MOD;
            else probability=probability*(MOD+1-p[4][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) probability=probability*p[5][j]%MOD;
            else probability=probability*(MOD+1-p[5][j])%MOD;
        }
        if (probability==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                nmsk^=A;
                                update_add(Xarr[nmsk], int(probability));
                            }
                        }
                    }
                }
            }
        }
    }

    fw_transform(Xarr, 1);
    fw_transform(Yarr, 1);
    for (int i=0; i<1048576; i++){
        Xarr[i]=1LL*Xarr[i]*Yarr[i]%MOD;
    }
    fw_transform(Xarr, -1);
    int answer=0;
    for (int i=1; i<1048576; i++) update_add(answer, Xarr[i]);
    printf("%d\n", answer);
    return 0;
}
